{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C63"],
      "claim": "Moxifloxacin, the closest analogue (Morgan 0.5844), has an absolute oral bioavailability of 86.2 ± 1.11% in healthy volunteers; the query shares the 8-methoxy, N-cyclopropyl, 6-fluoro-4-oxo-quinoline-3-carboxylic acid core, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Clinafloxacin (Morgan 0.4868), a 7-amino-substituted fluoroquinolone, has absolute oral bioavailability of approximately 90% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Nemonoxacin (Morgan 0.4321), which like the query has an 8-methoxy and a 7-piperidine-type substituent, shows nearly 100% absolute oral bioavailability in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Gemifloxacin (Morgan 0.4253), a fluoroquinolone with a somewhat lower but still high absolute oral bioavailability of approximately 71% (95% CI 60–84%), confirms that even the lower end of this class is far above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fleroxacin (Morgan 0.4079) is completely absorbed orally, with an absolute bioavailability of 100% at 400 mg, supporting the general fluoroquinolone pattern of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Levofloxacin (Morgan 0.3951) has an absolute oral bioavailability of approximately 99% in healthy volunteers, providing additional class-level support for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Finafloxacin (Morgan 0.3933), despite a wider reported range, has absolute bioavailability from approximately 60% to essentially complete, still well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence from structurally related fluoroquinolones—moxifloxacin, clinafloxacin, nemonoxacin, gemifloxacin, fleroxacin, levofloxacin, and finafloxacin—shows absolute oral bioavailability well above 20% (mostly 70–100%). The query retains the same fluoroquinolone scaffold and is therefore predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule; predictions rely on structurally related fluoroquinolones with moderate Morgan similarity.",
    "The query's unusual 7-substituent (exocyclic fluoromethylene aminomethyl piperidine) is not represented by an exact analogue, so its effect on absorption is inferred rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

